/// The classes the block's words read (`lf`, `word`, `dot`, `sign`, `exp_l`, `digit`, `pfx`, `quote`, `opens`, `closes`, `hash`, `rbrace`, `lbrace`, `ws`, `tab_ff`), each's bits in the block at `base`, a byte of the file: one load, and one
/// classify a pair of nibble tables, as the lean lexer's `Window`. None past the file.
#[inline(always)]
unsafe fn block_classes(src: &[u8], n: usize, base: usize) -> [u64; 15] {
    let block: &[u8; 64] = src[base..base + 64].try_into().expect("the padded source");
    let lv = valid(n, base as isize);
    // The block's load and its tables (safe: `std::simd`'s operations).
    {
        let v = s::load(block);
        let c0 = s::classify(v, &LO_0, &HI_0);
        let c1 = s::classify(v, &LO_1, &HI_1);
        let c2 = s::classify(v, &LO_2, &HI_2);
        let c4 = s::classify(v, &LO_4, &HI_4);
        [s::eq_mask(v, 0x0a) & lv, s::to_bitmask(s::test(c0, s::splat(0x78))) & lv, s::eq_mask(v, 0x2e) & lv, s::to_bitmask(s::test(c2, s::splat(0x80))) & lv, s::to_bitmask(s::test(c4, s::splat(0x08))) & lv, s::to_bitmask(s::test(c0, s::splat(0x08))) & lv, s::to_bitmask(s::test(c1, s::splat(0xc0))) & lv, s::to_bitmask(s::test(c0, s::splat(0x80))) & lv, s::to_bitmask(s::test(c1, s::splat(0x03))) & lv, s::to_bitmask(s::test(c1, s::splat(0x0c))) & lv, s::eq_mask(v, 0x23) & lv, s::eq_mask(v, 0x7d) & lv, s::eq_mask(v, 0x7b) & lv, s::to_bitmask(s::test(c0, s::splat(0x06))) & lv, s::to_bitmask(s::test(c1, s::splat(0x20))) & lv]
    }
}


/// String reader `string`'s text from its byte `o1` to its closer or an interpolation's `{`, from stop to stop (the lean
/// lexer's `string`'s loop), the string's quote `qi`, its flags `fl`, its region from `seg`: its pieces written after
/// record `len` (`more` of them, written where `WRITE`), each of its kind in `kinds` (0 its text, 1 an escape, 2 a lone escape, 3 a brace pair, 4 its closer, 5 an interpolation's `{`). The closer's first and last byte, and whether it is
/// a `{`; none where the file is refused.
#[inline(always)]
unsafe fn string_text<const WRITE: bool>(src: &[u8], n: usize, out: *mut Rec, len: usize, more_io: &mut usize, qi: u8, fl: u8, seg: usize, o1: usize, kinds: [u32; 6]) -> Option<(usize, usize, bool)> {
    let mut more = *more_io;
    let mut t0 = o1;
    // Its text, from stop to stop (the lean lexer's `string_stop`): its quote, its escape, an interpolation's braces.
    let mut at = t0;
    let (c, cl, to_code) = loop {
        let Some(p) = (if fl & 0x04 != 0 { wfirst_bit(n, at, |p: isize, esc: &mut u64| unsafe { w_t93(src, n, p, esc) }) } else { wfirst_bit(n, at, |p: isize, esc: &mut u64| unsafe { w_t92(src, n, p, esc) }) }) else {
            // A string open at the file's end.
            return None;
        };
        if ((p < n && (src[p] == b'\\'))) {
            if fl & 0x01 != 0 {
                // A raw string reads no escape: its backslash keeps a quote or a backslash after it from closing it or escaping.
                at = p + 1 + usize::from((((p + 1 < n && (src[p + 1] == b'\'')) || (p + 1 < n && (src[p + 1] == b'"')))) || ((p + 1 < n && (src[p + 1] == b'\\'))));
                continue;
            }
            if t0 < p {
                {
            let (a, z) = (t0, p - 1);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[0] }) };
            }
            more += 1;
        }
            }
        if ((p + 1 < n && (src[p + 1] == b'N'))) {
            // a `\N{…}` escape
            return None;
        }
        if fl & 0x02 != 0 && ((p + 1 < n && matches!(src[p + 1], b'N' | b'u' | b'U'))) {
            // a `\N`, `\u` or `\U` in a bytes string
            return None;
        }
            // By its check, else a `\` of one byte (the lean lexer's `backslash`): a quote after it is text.
            match check_escape_sequence(&src[p..]) {
                Some(k) => {
                    {
            let (a, z) = (p, p + k - 1);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[1] }) };
            }
            more += 1;
        }
                    at = p + k;
                    t0 = at;
                }
                None => {
                    {
            let (a, z) = (p, p);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[2] }) };
            }
            more += 1;
        }
                    t0 = p + 1;
                    at = p + 1 + usize::from((((p + 1 < n && (src[p + 1] == b'\'')) || (p + 1 < n && (src[p + 1] == b'"')))));
                }
            }
            continue;
        }
        if ((p < n && (src[p] == b'{'))) || ((p < n && (src[p] == b'}'))) {
            let open = ((p < n && (src[p] == b'{')));
            let r = if open { wrun_last(n, p, |p: isize, esc: &mut u64| unsafe { w_m_lbrace(src, n, p, esc) }) } else { wrun_last(n, p, |p: isize, esc: &mut u64| unsafe { w_m_rbrace(src, n, p, esc) }) };
            if !open {
            if (r + 1 - p) % 2 == 1 {
            // a `}` alone in an f-string's text
            return None;
            }
            }
            if t0 < p {
                {
            let (a, z) = (t0, p - 1);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[0] }) };
            }
            more += 1;
        }
            }
            for i in 0..(r + 1 - p) / 2 {
                {
            let (a, z) = (p + 2 * i, p + 2 * i + 1);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[3] }) };
            }
            more += 1;
        }
            }
            if open && (r + 1 - p) % 2 == 1 {
                break (r, r, true);
            }
            at = r + 1;
            t0 = at;
            continue;
        }
        // A quote: its own closes it (a triple's, the last three of a run); another is text.
        if !(match qi { 0 => ((p < n && (src[p] == b'\''))), _ => ((p < n && (src[p] == b'"'))) }) {
            at = p + 1;
            continue;
        }
        if fl & 0x80 != 0 && !(match qi { 0 => ((((((p < n && (src[p] == b'\'')) && (p + 1 < n && (src[p + 1] == b'\''))) && (p + 2 < n && (src[p + 2] == b'\''))) && (p < n && !(p + 3 < n && (src[p + 3] == b'\'')))) && (p < n && !{ let mut k2 = p; let mut odd = false; while k2 > 0 && (k2 - 1 < n && (src[k2 - 1] == b'\\')) { odd = !odd; k2 -= 1; } odd }))), _ => ((((((p < n && (src[p] == b'"')) && (p + 1 < n && (src[p + 1] == b'"'))) && (p + 2 < n && (src[p + 2] == b'"'))) && (p < n && !(p + 3 < n && (src[p + 3] == b'"')))) && (p < n && !{ let mut k2 = p; let mut odd = false; while k2 > 0 && (k2 - 1 < n && (src[k2 - 1] == b'\\')) { odd = !odd; k2 -= 1; } odd }))) }) {
            at = p + 1;
            continue;
        }
        if t0 < p {
            {
            let (a, z) = (t0, p - 1);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[0] }) };
            }
            more += 1;
        }
        }
        break (p, if fl & 0x80 != 0 { p + 2 } else { p }, false);
    };
    if wfirst_in(n, seg, c - 1, |p: isize, esc: &mut u64| unsafe { l_t81(src, n, p, esc, upto(p, c - 1)) }).is_some() {
        // a string open at the end of the file
        return None;
    }
    if fl & 0x80 == 0 && wfirst_in(n, seg, c - 1, |p: isize, esc: &mut u64| unsafe { l_t82(src, n, p, esc, upto(p, c - 1)) }).is_some() {
        // a line break in a one-line string that no backslash escapes
        return None;
    }
    if wfirst_in(n, seg, c - 1, |p: isize, esc: &mut u64| unsafe { l_m_cr(src, n, p, esc, upto(p, c - 1)) }).is_some() {
        // a carriage return in a string
        return None;
    }
    if fl & 0x80 != 0 && (match qi { 0 => wfirst_in(n, o1, c - 1, |p: isize, esc: &mut u64| unsafe { l_t84(src, n, p, esc, upto(p, c - 1)) }).is_some(), _ => wfirst_in(n, o1, c - 1, |p: isize, esc: &mut u64| unsafe { l_t85(src, n, p, esc, upto(p, c - 1)) }).is_some() }) {
        // a triple-quoted string closed by four quotes or more
        return None;
    }
    if fl & 0x01 != 0 && o1 < c && !wfirst_in(n, o1, c - 1, |p: isize, esc: &mut u64| unsafe { l_t91(src, n, p, esc, upto(p, c - 1)) }).is_some() {
        // a raw string of backslashes only
        return None;
    }
    if to_code {
        {
            let (a, z) = (c, c);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[5] }) };
            }
            more += 1;
        }
    } else {
        {
            let (a, z) = (c, cl);
            // SAFETY: room for a record a byte: the piece's first byte is after the record before's last.
            if WRITE {
                unsafe { out.add(len + 1 + more).write(Rec { start: a as u32, last: z as u32, code: kinds[4] }) };
            }
            more += 1;
        }
    }
    *more_io = more;
    Some((c, cl, to_code))
}

/// The words the grammar reads, a word's code its place plus one, as the lean lexer's `WORD_LIST`.
const WORD_LIST: [&[u8]; 90] = [
    b"False", b"None", b"True", b"and", b"as", b"assert", b"break", b"class", b"continue", b"def", b"del", b"elif",
    b"else", b"except", b"finally", b"for", b"from", b"global", b"if", b"import", b"in", b"is", b"lambda", b"nonlocal",
    b"not", b"or", b"pass", b"raise", b"return", b"try", b"while", b"with", b"yield", b"(", b")", b"[",
    b"]", b"{", b"}", b",", b":", b";", b".", b"=", b"+", b"-", b"*", b"/",
    b"%", b"&", b"|", b"^", b"~", b"<", b">", b"@", b"!", b"**", b"//", b"==",
    b"!=", b"<=", b">=", b"<<", b">>", b"->", b"+=", b"-=", b"*=", b"/=", b"%=", b"&=",
    b"|=", b"^=", b"@=", b":=", b"<>", b"**=", b"//=", b"<<=", b">>=", b"async", b"await", b"match",
    b"case", b"type", b"print", b"exec", b"__future__", b"_",
];

/// Up to 8 bytes as one word of memory: little-endian, zeros past them.
const fn word_key(s: &[u8]) -> u64 {
    let (mut v, mut i) = (0u64, 0);
    while i < s.len() {
        v |= (s[i] as u64) << (8 * i);
        i += 1;
    }
    v
}

/// A word's slot in `WORDS`: its first 8 bytes and its length, hashed by a multiplier under which the 90 words take
/// 90 slots, as the lean lexer's `word_slot`.
const fn word_slot(k: u64, len: usize) -> usize {
    ((k ^ len as u64).wrapping_mul(0xd93006c5bf09b337) >> 55) as usize
}

/// Each slot's word (`word_at`): its first 8 bytes, the next 8, its length, its code (0: none), as the lean lexer's
/// `WORDS`.
static WORDS: [(u64, u64, u32, u32); 512] = {
    let mut t = [(0, 0, 0, 0); 512];
    let mut i = 0;
    while i < WORD_LIST.len() {
        let w = WORD_LIST[i];
        let (head, tail) = w.split_at(if w.len() > 8 { 8 } else { w.len() });
        let slot = word_slot(word_key(head), w.len());
        assert!(t[slot].3 == 0, "two words in a slot");
        t[slot] = (word_key(head), word_key(tail), w.len() as u32, i as u32 + 1);
        i += 1;
    }
    t
};

/// A token's word: the code of the word its `len` bytes from `s` are, 0 for none, as the lean lexer's `word_code`. Its
/// first 8 bytes, masked to its length, and the length, hashed by one multiply into `WORDS`; its bytes 8 to 16 masked
/// the same, compared with the first and the length in one test (lean's `ninth`), without a branch.
#[inline(always)]
fn word_at(src: &[u8], s: usize, len: usize) -> u32 {
    let raw = u64::from_le_bytes(src[s..s + 8].try_into().expect("the padded source"));
    let rest = u64::from_le_bytes(src[s + 8..s + 16].try_into().expect("the padded source"));
    let k = raw & (u64::MAX >> (64 - 8 * len.clamp(1, 8)));
    let t = rest & u64::MAX.checked_shr(128 - 8 * len.clamp(8, 16) as u32).unwrap_or(0);
    let (key, tail, l, code) = WORDS[word_slot(k, len)];
    code & 0u32.wrapping_sub(u32::from((key == k) & (tail == t) & (l as usize == len)))
}


/// The marks tier 1's records leave to tier 2 (decisions 0623, 0655): those it asks of the bytes (`ASKED`), those whose
/// token tests it asks (`TESTED`), and the token marks its code reads no bit of (it asks them of the tokens).
pub const UNRECORDED: u32 = 0x1c;

/// The marks whose token tests tier 2 asks (decision 0655 step 6): none, the records hold them.
pub const TESTED: u32 = 0;

/// Whether a token test of mark `b` holds at grammar token `j`: never asked.
pub fn tested(src: &[u8], recs: &[Rec], xs: &[Rec], j: usize, b: u32) -> bool {
    let _ = (src, recs, xs, j, b);
    false
}

/// The gap marks tier 1 writes one bit for, the carrier's, the others of its mask asked of it where a rule reads one
/// (decision 0703), as the lean parser asks `asi` of a token's `nl`.
pub const DERIVED: u32 = 0x4;

/// Whether derived mark `b` holds at a token whose marks are `marks`, after a token of word `before`.
#[inline(always)]
pub fn derived(b: u32, marks: u32, before: u32) -> bool {
    let _ = before;
    match b {
        2 => marks >> 0 & 1 == 1,
        _ => false,
    }
}

/// Marks `bits` with the carriers of the derived ones (`DERIVED`): an extra's own, read of its code, after a grammar
/// token of word `before`. A mark whose mask holds its `unless after` (`under_unless`) holds none after those words.
#[inline(always)]
pub const fn carried(before: u32, bits: u32) -> u32 {
    let _ = before;
    let mut r = bits;
    if bits >> 2 & 1 == 1 {
        r |= 1 << 0;
    }
    r
}

/// The gap marks tier 2 asks of the spans between the records where a rule reads one (decision 0703), as the lean
/// parser asks whether two tokens touch and whether a line breaks since the token before: tier 1 writes no bit of them.
pub const SPANNED: u32 = 0x0;

/// Whether spanned mark `b` holds at a grammar token starting at `s`: `ps` and `pe` the first byte and the byte after the
/// grammar token before (0: none), `xend` the byte after the extra before (0: none), `before` the grammar token before's
/// word.
#[inline]
pub fn spanned(src: &[u8], ps: usize, pe: usize, xend: usize, s: usize, before: u32, b: u32, code: &dyn Fn(usize) -> bool) -> bool {
    let _ = (src, ps, pe, xend, s, before, b, code);
    false
}

/// Whether byte `q` is code, of tier 1's records (`recs`, the extras `xs`): no extra holds it, nor a token of a region
/// (a string's, a character's, a name in backticks), as the grammar's `code` is none of a region's bytes.
pub fn code_at(recs: &[Rec], xs: &[Rec], q: usize) -> bool {
    let q = q as u32;
    let within = |rs: &[Rec]| rs.partition_point(|r| r.start <= q).checked_sub(1).is_some_and(|k| rs[k].last >= q);
    let k = recs.partition_point(|r| r.start <= q);
    let region = k > 0 && recs[k - 1].last >= q && matches!(recs[k - 1].code & 0xff, 2 | 3 | 14);
    !region && !within(xs)
}

/// The gap marks tier 2 asks of the bytes, where a rule asks one (decision 0623 step 5), by their bits: tier 1's
/// records hold only its token tests' hits of them.
pub const ASKED: u32 = 0x0;

/// Whether gap mark `b` holds over `src[from..to]`, the bytes since the grammar token before's first byte (`before` its
/// word), as the lean parser asks whether a token is on a line.
#[inline]
pub fn gap(src: &[u8], from: usize, to: usize, before: u32, b: u32) -> bool {
    let _ = (src, from, to, before, b);
    false
}

// Lexing from the middle (the chunk-summaries design): the token loop's state between two tokens, the loop from any of
// them to any block, and the three passes. Pass 1 lexes each chunk from each class of entries (`chunk_ends`), pass 3
// composes the chunks' summaries by a prefix sum (`entries`), pass 2 lexes each chunk from its entry (`lex_chunked`).

/// The token loop's state between two tokens: where the next token starts (`at`), the nest (`nest[..depth]`, its top
/// `template`), the strings its templates hold open (`held[..opened]`, their records), and what the loop keeps of the
/// token before. The serial lexer's at each chunk's start is that chunk's entry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Entry {
    pub at: usize,
    pub pending: u32,
    pub acc_0: bool,
    pub rec_0: bool,
    pub c_depth: u32,
    pub rd_on: bool,
    pub rd_q: u8,
    pub rd_fl: u8,
    pub rd_level: u8,
    pub rd_total: u8,
    pub rd_open: usize,
    pub rd_around: [(u8, u8, u8); 3],
    pub rd_depth: usize,
    pub rd_code: usize,
    pub more: usize,
    pub rd_end: usize,
    pub rd_bare: bool,
}

impl Entry {
    /// The file's first byte: in code, nothing open.
    pub const START: Entry = Entry { at: 0usize, pending: 0u32, acc_0: false, rec_0: false, c_depth: 0u32, rd_on: false, rd_q: 0u8, rd_fl: 0u8, rd_level: 0u8, rd_total: 0u8, rd_open: 0usize, rd_around: [(0u8, 0u8, 0u8); 3], rd_depth: 0usize, rd_code: usize::MAX, more: 0usize, rd_end: usize::MAX, rd_bare: false, };
}


